def authoring_package_inventory(previous_output: Path) -> list[dict[str, Any]]:
    """Validate retained V3 records and enumerate only their package dependencies."""
    from .workspace_notes import note_contract_metadata, read_note_body

    packages: list[dict[str, Any]] = []
    for note_path in sorted((previous_output / "workspace-meta/notes").glob("*.json")):
        metadata = json_load(note_path)
        contract = metadata.get("human_output_contract") or {}
        if not (metadata.get("authoring_package") or metadata.get("section_evidence")
                or contract.get("v3_validated")):
            continue
        try:
            manifest_path = Path(metadata["authoring_package"]).resolve()
            if manifest_path.name != "manifest.json" or not manifest_path.is_file():
                raise CkbError("V3 authoring manifest is missing or not manifest.json")
            body_path = manifest_path.parent / "body.md"
            body = read_note_body(body_path)
            if hashlib.sha256((body.rstrip() + "\n").encode("utf-8")).hexdigest() != metadata.get("body_sha256"):
                raise CkbError("V3 record body digest differs from its authoring package")
            verified = note_contract_metadata(body_path, metadata["kind"], body)
            if not verified["human_output_contract"]["v3_validated"]:
                raise CkbError("retained V3 record has no validated authoring package")
            for field in ("validation_context", "section_evidence", "section_evidence_sha256"):
                if metadata.get(field) != verified[field]:
                    raise CkbError(f"V3 record and authoring package metadata drift: {field}")
            files: dict[str, dict[str, Any]] = {}

            def add(path: Path, role: str) -> None:
                if not path.resolve().is_relative_to(manifest_path.parent):
                    raise CkbError(f"V3 authoring file escapes its package: {path}")
                relative = path.relative_to(manifest_path.parent).as_posix()
                if relative not in files:
                    files[relative] = {"source": str(path), "relative_path": relative,
                                       "sha256": sha256_file(path), "roles": []}
                if role not in files[relative]["roles"]:
                    files[relative]["roles"].append(role)

            add(manifest_path, "manifest")
            add(body_path, "body")
            for section in verified["section_evidence"].get("sections", []):
                for field in ("source_refs", "machine_evidence_refs"):
                    for ref in section.get(field, []):
                        if ref.get("target_basis") == "uri":
                            continue
                        # The shared validator already checked containment and the declared digest.
                        add((manifest_path.parent / ref["target"]).resolve(), field)
            digest = files["manifest.json"]["sha256"]
            if (manifest_path.parent.parent == (previous_output / "machine/authoring").resolve()
                    and manifest_path.parent.name != digest[:20]):
                raise CkbError("V3 archived authoring manifest digest drift")
            packages.append({
                "note_relative": note_path.relative_to(previous_output).as_posix(),
                "source_manifest": str(manifest_path),
                "archive_relative": f"machine/authoring/{digest[:20]}",
                "files": [files[key] for key in sorted(files)],
            })
        except (CkbError, OSError, KeyError, TypeError, ValueError) as exc:
            raise CkbError(f"V3 authoring package preflight failed for {note_path.name}: {exc}") from exc
    return packages

def add(path: Path, role: str) -> None:
                if not path.resolve().is_relative_to(manifest_path.parent):
                    raise CkbError(f"V3 authoring file escapes its package: {path}")
                relative = path.relative_to(manifest_path.parent).as_posix()
                if relative not in files:
                    files[relative] = {"source": str(path), "relative_path": relative,
                                       "sha256": sha256_file(path), "roles": []}
                if role not in files[relative]["roles"]:
                    files[relative]["roles"].append(role)

def audit_migration(output: Path, *, require_complete_reviews: bool = True) -> dict[str, Any]:
    output = output.resolve()
    state = json_load(output / "state.json")
    plan_path = output / "migration" / "plan.json"
    checks: list[dict[str, Any]] = []

    def check(name: str, passed: bool, detail: Any) -> None:
        checks.append({"name": name, "passed": bool(passed), "detail": detail})

    check("migration-plan-present", plan_path.is_file(), str(plan_path))
    if not plan_path.is_file():
        result = {"schema_version": MIGRATION_SCHEMA_VERSION, "status": "failed", "checks": checks, "audited_at_utc": utc_now()}
        json_write(output / "migration" / "audit.json", result)
        return result
    plan = json_load(plan_path)
    migration = state.get("migration") or {}
    check("target-version-current", state.get("version") == VERSION and migration.get("target_version") == VERSION, {"state": state.get("version"), "target": migration.get("target_version")})
    check("target-commit-pinned", state.get("repository", {}).get("commit") == plan.get("target", {}).get("commit"), state.get("repository", {}).get("commit"))
    catalog = json_load(output / "catalog.json")
    reused_paths = set(plan.get("files", {}).get("reused", []))
    catalog_reused = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
    check("exact-blob-reuse-set", reused_paths == catalog_reused, {"missing": sorted(reused_paths - catalog_reused), "extra": sorted(catalog_reused - reused_paths)})
    reused_records = {
        item["file"]["path"]: item
        for item in catalog.get("files", [])
        if item["file"]["path"] in reused_paths
    }
    reuse_errors = [
        path
        for path in sorted(reused_paths)
        if path not in reused_records or not reused_records[path].get("migration_reuse")
    ]
    check("reused-files-carry-rekey-proof", not reuse_errors, reuse_errors)
    mutable_errors: list[dict[str, Any]] = []
    retired_reference_status_markers: list[str] = []
    for item in plan.get("mutable_files", []):
        relative_target = str(item.get("relative_target") or "")
        baseline_relative = str(item.get("baseline_relative_target") or "")
        try:
            target = _mutable_target(output, relative_target)
            baseline = _mutable_target(output, baseline_relative)
        except CkbError as exc:
            mutable_errors.append({"path": relative_target, "reason": str(exc)})
            continue
        expected_baseline = item.get("baseline_sha256")
        if not baseline.is_file() or not expected_baseline or sha256_file(baseline) != expected_baseline:
            mutable_errors.append({"path": relative_target, "reason": "preserved-baseline-missing-or-changed"})
            continue
        # Reference audits replace these three mutually exclusive generated
        # markers. Keep their original bytes, not their obsolete live presence.
        # Legacy staging plans classified the same paths as reference sources.
        reference_marker = (
            target.relative_to(output).as_posix() in REFERENCE_STATUS_MARKERS
            and item.get("kind") in {"reference-status-marker", "reviewed-reference-source"}
        )
        if reference_marker and not target.exists():
            retired_reference_status_markers.append(target.relative_to(output).as_posix())
            continue
        if not target.is_file():
            mutable_errors.append({"path": relative_target, "reason": "live-mutable-file-missing"})
            continue
        if item.get("kind") in {"referenced-machine-evidence", "authoring-package-file", "transaction-archive-file"} and sha256_file(target) != expected_baseline:
            mutable_errors.append({"path": relative_target, "reason": "referenced-machine-evidence-changed"})
            continue
        try:
            suffix = target.suffix.casefold()
            if suffix == ".json" or reference_marker:
                json_load(target)
            elif suffix == ".md":
                target.read_text(encoding="utf-8")
            elif suffix in {".sqlite", ".db"}:
                connection = sqlite3.connect(f"file:{target.as_posix()}?mode=ro", uri=True)
                try:
                    integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
                finally:
                    connection.close()
                if integrity != "ok":
                    raise CkbError(f"SQLite integrity_check returned {integrity}")
            else:
                target.read_bytes()
        except (CkbError, OSError, UnicodeError, json.JSONDecodeError, sqlite3.Error) as exc:
            mutable_errors.append({"path": relative_target, "reason": "live-mutable-file-invalid", "detail": str(exc)})
    check("mutable-layers-preserved", not mutable_errors, mutable_errors)
    review_status = {pack["id"]: pack.get("status") for pack in state.get("review_packs", [])}
    reviews_complete = bool(review_status) and all(value == "passed" for value in review_status.values())
    check("migration-review-state", reviews_complete if require_complete_reviews else True, review_status)
    graph_path = output / "graph.json"
    graph_errors: list[Any] = []
    if graph_path.is_file():
        graph = json_load(graph_path)
        target_commit = state["repository"]["commit"]
        id_map = plan.get("entities", {}).get("old_to_new_id_map", {})
        # A CKB-version-only migration may retain the same fixed Git commit.
        # In that case commit-sensitive IDs are intentionally identical and
        # are not obsolete IDs.  Only mappings whose target actually changed
        # may be treated as forbidden old-ID residue.
        old_ids = {old for old, new in id_map.items() if old != new}
        new_ids = {entity["id"] for entity in graph.get("entities", [])}
        if old_ids & new_ids:
            graph_errors.append({"reason": "old-entity-id-remains", "ids": sorted(old_ids & new_ids)[:20]})
        wrong_commit = [entity["id"] for entity in graph.get("entities", []) if entity.get("commit") != target_commit]
        if wrong_commit:
            graph_errors.append({"reason": "entity-commit-mismatch", "ids": wrong_commit[:20]})
    elif require_complete_reviews:
        graph_errors.append({"reason": "graph-not-merged"})
    check("target-graph-has-only-new-provenance", not graph_errors, graph_errors)
    all_checks_passed = all(item["passed"] for item in checks)
    if all_checks_passed and reviews_complete:
        status = "passed"
    elif all_checks_passed and not require_complete_reviews:
        status = "pending-agent-review"
    else:
        status = "failed"
    result = {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": status,
        "checks": checks,
        "counts": {"passed": sum(item["passed"] for item in checks), "total": len(checks)},
        "retired_reference_status_markers": sorted(retired_reference_status_markers),
        "audited_at_utc": utc_now(),
    }
    if status == "passed":
        plan["status"] = "passed"
        json_write(plan_path, plan)
        state["migration"] = {**migration, "status": "passed", "audited_at_utc": result["audited_at_utc"]}
        json_write(output / "state.json", state)
    json_write(output / "migration" / "audit.json", result)
    return result

def _semantic_page_key(entity: dict[str, Any]) -> tuple[str, str, str]:
    kind = "file" if entity.get("kind") == "file" else str(entity.get("kind_original") or entity.get("kind"))
    return (str(entity.get("path")), kind, str(entity.get("qualified_name") or entity.get("name")))

def relink_preserved_notes(output: Path, graph: dict[str, Any], projection: dict[str, Any]) -> dict[str, Any]:
    """Retarget preserved Wiki links after deterministic human titles change."""
    output = output.resolve()
    plan_path = output / "migration" / "plan.json"
    if not plan_path.is_file():
        return {"schema_version": MIGRATION_SCHEMA_VERSION, "status": "not-applicable", "changed_files": []}
    plan = json_load(plan_path)
    origin = Path(plan["origin"]["output"])
    old_graph_path = origin / "graph.json"
    old_projection_path = origin / "markdown" / "projection.json"
    if not old_graph_path.is_file() or not old_projection_path.is_file():
        raise CkbError(f"migration note relink requires the origin graph and Markdown projection: {origin}")
    old_graph = json_load(old_graph_path)
    old_projection = json_load(old_projection_path)
    old_entities = {entity["id"]: entity for entity in old_graph.get("entities", [])}
    new_by_key: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
    for entity in graph.get("entities", []):
        new_by_key.setdefault(_semantic_page_key(entity), []).append(entity)
    new_pages = {page["id"]: page for page in projection.get("pages", [])}
    old_owners = old_projection.get("entity_owner_pages", {})
    new_owners = projection.get("entity_owner_pages", {})
    title_map: dict[str, str] = {}
    unresolved: list[dict[str, Any]] = []

    def owner_for(old_entity: dict[str, Any]) -> str | None:
        matches = new_by_key.get(_semantic_page_key(old_entity), [])
        if len(matches) != 1:
            return None
        entity = matches[0]
        owner = new_owners.get(entity["id"]) or entity.get("owner_page_id") or entity["id"]
        return owner if owner in new_pages else None

    new_modules: dict[str, set[str]] = {}
    for link in projection.get("links", []):
        if link.get("type") == "contains-file":
            new_modules.setdefault(link["target"], set()).add(link["source"])
    for page in old_projection.get("pages", []):
        old_title = page.get("title")
        if not old_title:
            continue
        old_entity = old_entities.get(page.get("id"))
        candidates: list[str | None] = []
        if old_entity:
            candidates = [owner_for(old_entity)]
        elif page.get("page_type") == "boundary":
            members = [entity for entity in old_entities.values() if old_owners.get(entity["id"]) == page["id"]]
            candidates = [owner_for(entity) for entity in members]
        elif page.get("page_type") == "module":
            members = [old_entities.get(link["target"]) for link in old_projection.get("links", [])
                       if link.get("type") == "contains-file" and link.get("source") == page["id"]]
            for entity in members:
                modules = new_modules.get(owner_for(entity), set()) if entity else set()
                candidates.append(next(iter(modules)) if len(modules) == 1 else None)
        elif page.get("page_type") == "repository":
            old_root = old_graph.get("repository", {}).get("root")
            new_root = graph.get("repository", {}).get("root")
            if old_root and new_root and Path(old_root).resolve() == Path(new_root).resolve():
                candidates = [key for key, value in new_pages.items() if value.get("page_type") == "repository"]
        if not candidates or None in candidates or len(set(candidates)) != 1:
            unresolved.append({"old_title": old_title, "reason": "no-unique-semantic-owner"})
            continue
        new_title = new_pages[candidates[0]]["title"]
        if old_title != new_title:
            title_map[str(old_title)] = str(new_title)

    def replace_links(text: str) -> str:
        # One substitution pass avoids A->B->C cascades. Only actual Wiki-link
        # targets change; prose, aliases, inline code and fenced examples stay.
        lines = []
        fence = None
        for line in text.splitlines(keepends=True):
            marker = re.match(r"^\s*(`{3,}|~{3,})", line)
            if marker:
                token = marker.group(1)
                if fence is None:
                    fence = token
                elif token[0] == fence[0] and len(token) >= len(fence):
                    fence = None
                lines.append(line)
                continue
            if fence is not None:
                lines.append(line)
                continue
            parts = re.split(r"(`+[^`]*`+)", line)
            for index in range(0, len(parts), 2):
                parts[index] = re.sub(r"\[\[([^\]|#]+)([^\]]*)\]\]",
                    lambda match: "[[" + title_map.get(match.group(1), match.group(1)) + match.group(2) + "]]", parts[index])
            lines.append("".join(parts))
        return "".join(lines)

    changed: list[str] = []
    for item in plan.get("mutable_files", []):
        if item.get("kind") in {"referenced-machine-evidence", "authoring-package-file", "transaction-archive-file"}:
            continue
        target = _mutable_target(output, str(item["relative_target"]))
        if not target.is_file():
            continue
        if (plan.get("note_relink", {}).get("title_map") == title_map
                and item.get("post_migration_sha256") == sha256_file(target)):
            continue
        if target.suffix.casefold() == ".md":
            text = target.read_bytes().decode("utf-8")
            updated = replace_links(text)
            if updated != text:
                target.write_bytes(updated.encode("utf-8"))
                changed.append(item["relative_target"])
        elif target.suffix.casefold() == ".json" and "workspace-meta" in target.parts:
            try:
                value = json_load(target)
            except (json.JSONDecodeError, OSError):
                continue
            updated = False
            linked = value.get("linked_pages")
            if isinstance(linked, list):
                replacement = [title_map.get(str(page), str(page)) for page in linked]
                if replacement != linked:
                    value["linked_pages"] = replacement
                    updated = True
            for field, root_name in (("file", "human"), ("compatibility_file", "markdown")):
                current = value.get(field)
                if isinstance(current, str):
                    candidate = output / root_name / Path(current.replace("\\", "/")).name
                    kind = str(value.get("kind") or "session")
                    directory = {"change": "changes", "analysis": "analysis", "pitfall": "pitfalls", "experiment": "experiments", "session": "sessions"}.get(kind, "user")
                    candidate = output / root_name / directory / candidate.name
                    rendered = str(candidate.resolve())
                    if rendered != current:
                        value[field] = rendered
                        updated = True
            if isinstance(value.get("compatibility_file"), str):
                uri = "obsidian://open?path=" + quote(value["compatibility_file"], safe="")
                if value.get("obsidian_uri") != uri:
                    value["obsidian_uri"] = uri
                    updated = True
            if updated:
                json_write(target, value)
                changed.append(item["relative_target"])
        item["post_migration_sha256"] = sha256_file(target)
        item["post_migration_size"] = target.stat().st_size
    plan["note_relink"] = {
        "status": "passed",
        "title_map": title_map,
        "unresolved_titles": unresolved,
        "changed_files": sorted(set(changed)),
        "updated_at_utc": utc_now(),
    }
    json_write(plan_path, plan)
    result = {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": "passed",
        "title_map_count": len(title_map),
        "changed_files": sorted(set(changed)),
        "title_map": title_map,
        "unresolved_titles": unresolved,
    }
    json_write(output / "migration" / "note-relink.json", result)
    return result

def replace_links(text: str) -> str:
        # One substitution pass avoids A->B->C cascades. Only actual Wiki-link
        # targets change; prose, aliases, inline code and fenced examples stay.
        lines = []
        fence = None
        for line in text.splitlines(keepends=True):
            marker = re.match(r"^\s*(`{3,}|~{3,})", line)
            if marker:
                token = marker.group(1)
                if fence is None:
                    fence = token
                elif token[0] == fence[0] and len(token) >= len(fence):
                    fence = None
                lines.append(line)
                continue
            if fence is not None:
                lines.append(line)
                continue
            parts = re.split(r"(`+[^`]*`+)", line)
            for index in range(0, len(parts), 2):
                parts[index] = re.sub(r"\[\[([^\]|#]+)([^\]]*)\]\]",
                    lambda match: "[[" + title_map.get(match.group(1), match.group(1)) + match.group(2) + "]]", parts[index])
            lines.append("".join(parts))
        return "".join(lines)

def migration_status(output: Path) -> dict[str, Any]:
    output = output.resolve()
    state = json_load(output / "state.json")
    migration = state.get("migration")
    if not migration:
        raise CkbError(f"output is not an incremental migration: {output}")
    pending = [pack for pack in state.get("review_packs", []) if pack.get("status") != "passed"]
    audit = audit_migration(output, require_complete_reviews=False)
    if state.get("status") == "complete" and audit.get("status") == "passed":
        status = "complete"
    else:
        status = "pending-agent-review" if pending else "ready-to-finalize"
    return {
        "schema_version": MIGRATION_SCHEMA_VERSION,
        "status": status,
        "migration": migration,
        "pending_review_packs": [pack["id"] for pack in pending],
        "next_review_template": pending[0].get("review_template_path") if pending else None,
        "audit": audit,
    }

class RecordReplaceLockError(CkbError):
    def __init__(self, category: str, message: str):
        super().__init__(f"{category}: {message}")
        self.category = category

def __init__(self, category: str, message: str):
        super().__init__(f"{category}: {message}")
        self.category = category

def _json_digest(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()

def _new_replace_lock_record(owner_token: str) -> dict[str, Any]:
    state, identity = _process_start_identity(os.getpid())
    if state != "alive" or not identity:
        raise RecordReplaceLockError(
            "record-replace-lock-owner-identity-unavailable",
            f"current process identity is unavailable for record replacement lock: {os.getpid()}",
        )
    return {
        "schema_version": REPLACE_LOCK_SCHEMA_VERSION,
        "owner_pid": os.getpid(),
        "owner_token": owner_token,
        "owner_process_start": identity,
        "owner_host": socket.gethostname(),
        "created_at_utc": utc_now(),
    }

def _parse_replace_lock(value: bytes) -> tuple[dict[str, Any] | None, str | None]:
    try:
        record = json.loads(value.decode("utf-8-sig"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record, dict) or set(record) != REPLACE_LOCK_FIELDS:
        return None, "record-replace-lock-record-invalid"
    if record.get("schema_version") != REPLACE_LOCK_SCHEMA_VERSION:
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record.get("owner_pid"), int) or record["owner_pid"] < 1:
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record.get("owner_token"), str) or not REPLACE_OWNER_TOKEN_PATTERN.fullmatch(record["owner_token"]):
        return None, "record-replace-lock-record-invalid"
    for field in ("owner_process_start", "owner_host", "created_at_utc"):
        if not isinstance(record.get(field), str) or not record[field] or len(record[field]) > 128:
            return None, "record-replace-lock-record-invalid"
    return record, None

def _replace_lock_owner_state(record: dict[str, Any]) -> str:
    if record["owner_host"] != socket.gethostname():
        return "record-replace-lock-owner-unverifiable"
    state, identity = _process_start_identity(int(record["owner_pid"]))
    if state == "dead":
        return "record-replace-lock-owner-dead"
    if state != "alive" or not identity:
        return "record-replace-lock-owner-unverifiable"
    if identity != record["owner_process_start"]:
        return "record-replace-lock-owner-pid-reused"
    return "record-replace-lock-owner-live"

def _release_replace_lock(lock: Path, descriptor: int, owner_token: str) -> None:
    category: str | None = None
    try:
        if not _same_owner_lock_file(lock, descriptor):
            category = "record-replace-lock-release-file-replaced"
        else:
            record, invalid = _parse_replace_lock(_owner_descriptor_bytes(descriptor))
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "record-replace-lock-release-owner-token-drift"
    finally:
        _owner_descriptor_unlock(descriptor)
        os.close(descriptor)
    if category is None:
        try:
            record, invalid = _parse_replace_lock(lock.read_bytes())
        except FileNotFoundError:
            category = "record-replace-lock-release-missing"
        else:
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "record-replace-lock-release-owner-token-drift"
            else:
                lock.unlink()
    if category:
        raise RecordReplaceLockError(category, f"record replacement lock ownership changed before release: {lock}")

def _replace_lock(output: Path) -> Iterator[dict[str, Any]]:
    root = _operation_root(output)
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + REPLACE_LOCK_TIMEOUT_SECONDS
    owner_token = uuid.uuid4().hex
    descriptor: int | None = None
    recovered_category: str | None = None
    last_category = "concurrent-record-replace-lock"
    while descriptor is None:
        created = False
        try:
            candidate = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_RDWR, 0o600)
            created = True
            os.write(candidate, b" ")
        except FileExistsError:
            try:
                candidate = os.open(lock, os.O_RDWR)
            except FileNotFoundError:
                continue
        if not _owner_descriptor_lock(candidate):
            os.close(candidate)
            last_category = "concurrent-record-replace-lock"
        elif not _same_owner_lock_file(lock, candidate):
            _owner_descriptor_unlock(candidate)
            os.close(candidate)
            continue
        elif created:
            _write_owner_lock_descriptor(candidate, _new_replace_lock_record(owner_token))
            descriptor = candidate
        else:
            age = max(0.0, time.time() - os.fstat(candidate).st_mtime)
            record, invalid = _parse_replace_lock(_owner_descriptor_bytes(candidate))
            if invalid or record is None:
                last_category = invalid or "record-replace-lock-record-invalid"
                recover = False
            else:
                last_category = _replace_lock_owner_state(record)
                recover = age > REPLACE_LOCK_STALE_SECONDS and last_category in {
                    "record-replace-lock-owner-dead",
                    "record-replace-lock-owner-pid-reused",
                }
                recovered_category = last_category if recover else None
            if recover:
                _write_owner_lock_descriptor(candidate, _new_replace_lock_record(owner_token))
                descriptor = candidate
            else:
                _owner_descriptor_unlock(candidate)
                os.close(candidate)
        if descriptor is None:
            if time.monotonic() >= deadline:
                raise RecordReplaceLockError(last_category, f"record replacement is busy: {lock}")
            time.sleep(0.05)
    body_error = False
    try:
        yield {
            "schema_version": REPLACE_LOCK_SCHEMA_VERSION,
            "owner_pid": os.getpid(),
            "owner_token": owner_token,
            "recovered_category": recovered_category,
            "_descriptor": descriptor,
        }
    except BaseException:
        body_error = True
        raise
    finally:
        try:
            _release_replace_lock(lock, descriptor, owner_token)
        except RecordReplaceLockError:
            if not body_error:
                raise

def _powershell_command(argv: list[str]) -> str:
    escaped = [value.replace("'", "''") for value in argv]
    return "& " + " ".join(f"'{value}'" for value in escaped)

def _read_title(path: Path) -> str:
    try:
        text = path.read_text(encoding="utf-8-sig")
    except UnicodeDecodeError as exc:
        raise CkbError(f"managed knowledge note must be valid UTF-8: {path}: {exc}") from exc
    return text.splitlines()[0].removeprefix("# ").strip() if text else ""

def _locate_existing(output: Path, kind: str, title: str) -> tuple[Path, Path, Path, dict[str, Any]]:
    filename = safe_title(title) + ".md"
    relative = Path(DIRECTORY_BY_KIND[kind]) / filename
    markdown = output / "markdown" / relative
    human = output / "human" / relative
    metadata = output / "workspace-meta/notes" / (safe_title(title) + ".json")
    if not markdown.is_file() or not human.is_file():
        for other_kind, directory in DIRECTORY_BY_KIND.items():
            for root_name in ("markdown", "human"):
                candidate = output / root_name / directory / filename
                if candidate.is_file() and _read_title(candidate) == title:
                    if other_kind != kind:
                        raise CkbError(
                            f"record replace kind mismatch for exact title {title}: existing={other_kind}; requested={kind}"
                        )
        raise CkbError(f"record replace target does not exist for exact kind and title: kind={kind}; title={title}")
    if _read_title(markdown) != title or _read_title(human) != title:
        raise CkbError(f"record replace target title differs from the requested exact title: {title}")
    if markdown.read_bytes() != human.read_bytes():
        raise CkbError(f"record replace baseline human/markdown mirrors differ: {relative.as_posix()}")
    if not metadata.is_file():
        raise CkbError(f"record replace metadata is missing: {metadata}")
    record = json_load(metadata)
    if record.get("title") != title:
        raise CkbError(f"record replace metadata title differs from the requested exact title: {title}")
    if record.get("kind") != kind:
        raise CkbError(
            f"record replace kind mismatch for exact title {title}: existing={record.get('kind')}; requested={kind}"
        )
    return relative, human, markdown, record

def _copy_candidate_note_roots(output: Path, candidate_output: Path) -> None:
    for root_name in ("human", "markdown"):
        source_root = output / root_name
        target_root = candidate_output / root_name
        target_root.mkdir(parents=True, exist_ok=True)
        projection = source_root / "projection.json"
        if projection.is_file():
            shutil.copy2(projection, target_root / "projection.json")
        for directory in NOTE_DIRECTORIES:
            source = source_root / directory
            target = target_root / directory
            if source.is_dir():
                shutil.copytree(source, target)
            else:
                target.mkdir(parents=True, exist_ok=True)
    gaps = output / "workspace-meta/gaps"
    if gaps.is_dir():
        shutil.copytree(gaps, candidate_output / "workspace-meta/gaps")

def _file_state(path: Path) -> dict[str, Any]:
    return {
        "exists": path.is_file(),
        "sha256": sha256_file(path) if path.is_file() else None,
        "size": path.stat().st_size if path.is_file() else 0,
    }

def _agent_snapshot(connection: sqlite3.Connection, title: str) -> dict[str, Any]:
    note = connection.execute(
        "SELECT note_title,tag,note_file,content,token_estimate FROM notes WHERE note_title=?",
        (title,),
    ).fetchall()
    links = connection.execute(
        "SELECT note_title,page_title FROM note_links WHERE note_title=? ORDER BY page_title",
        (title,),
    ).fetchall()
    fts = connection.execute(
        "SELECT note_title,title,content FROM note_fts WHERE note_title=?",
        (title,),
    ).fetchall()
    return {"note": [list(row) for row in note], "links": [list(row) for row in links], "fts": [list(row) for row in fts]}

def _agent_candidate(baseline: dict[str, Any], title: str, text: str, links: list[str]) -> dict[str, Any]:
    if len(baseline.get("note", [])) != 1:
        raise CkbError(f"agent-index.sqlite must contain exactly one work record for title: {title}")
    row = list(baseline["note"][0])
    row[3] = text
    row[4] = _token_estimate(text)
    return {
        "note": [row],
        "links": [[title, value] for value in sorted(set(links))],
        "fts": [[title, title, text]],
    }

def _apply_agent_state(connection: sqlite3.Connection, title: str, state: dict[str, Any]) -> None:
    if len(state.get("note", [])) != 1:
        raise CkbError(f"invalid agent-index candidate for title: {title}")
    cursor = connection.execute(
        "UPDATE notes SET tag=?,note_file=?,content=?,token_estimate=? WHERE note_title=?",
        (state["note"][0][1], state["note"][0][2], state["note"][0][3], state["note"][0][4], title),
    )
    if cursor.rowcount != 1:
        raise CkbError(f"agent-index work record disappeared during replacement: {title}")
    connection.execute("DELETE FROM note_links WHERE note_title=?", (title,))
    connection.execute("DELETE FROM note_fts WHERE note_title=?", (title,))
    connection.executemany("INSERT INTO note_links(note_title,page_title) VALUES(?,?)", state.get("links", []))
    connection.executemany("INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)", state.get("fts", []))

def _sqlite_integrity(connection: sqlite3.Connection, label: str) -> None:
    integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
    foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
    if integrity != "ok" or foreign_keys:
        raise CkbError(f"{label} candidate integrity failed: integrity={integrity}; foreign_keys={foreign_keys[:10]}")

def _trial_agent(path: Path, title: str, baseline: dict[str, Any], candidate: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(baseline):
            raise CkbError(f"agent-index target drifted before candidate validation: {title}")
        _apply_agent_state(connection, title, candidate)
        _sqlite_integrity(connection, "agent-index.sqlite")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(candidate):
            raise CkbError(f"agent-index candidate did not reopen exactly: {title}")
        connection.rollback()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()

def _trial_machine(path: Path, document_id: str, baseline: dict[str, Any], candidate: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(baseline):
            raise CkbError(f"machine knowledge target drifted before candidate validation: {document_id}")
        _apply_machine_state(connection, document_id, candidate)
        _sqlite_integrity(connection, "machine/knowledge.sqlite")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(candidate):
            raise CkbError(f"machine knowledge candidate did not reopen exactly: {document_id}")
        connection.rollback()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()

def _current_agent(path: Path, title: str) -> dict[str, Any]:
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        return _agent_snapshot(connection, title)
    finally:
        connection.close()

def _current_machine(path: Path, document_id: str) -> dict[str, Any]:
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        return _machine_snapshot(connection, document_id)
    finally:
        connection.close()

def _commit_agent(path: Path, title: str, expected: dict[str, Any], state: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(expected):
            raise CkbError(f"agent-index target drifted during promotion: {title}")
        _apply_agent_state(connection, title, state)
        _sqlite_integrity(connection, "agent-index.sqlite")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(state):
            raise CkbError(f"agent-index promoted state did not reopen exactly: {title}")
        connection.commit()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()

def _commit_machine(path: Path, document_id: str, expected: dict[str, Any], state: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(expected):
            raise CkbError(f"machine knowledge target drifted during promotion: {document_id}")
        _apply_machine_state(connection, document_id, state)
        _sqlite_integrity(connection, "machine/knowledge.sqlite")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(state):
            raise CkbError(f"machine knowledge promoted state did not reopen exactly: {document_id}")
        connection.commit()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()

def _cleanup_new_sqlite_sidecars(path: Path, baseline: dict[str, bool]) -> None:
    for suffix in ("-wal", "-shm", "-journal"):
        sidecar = Path(str(path) + suffix)
        if not baseline.get(suffix, False):
            sidecar.unlink(missing_ok=True)

def _restore_file(output: Path, role: dict[str, Any]) -> None:
    target = output / role["path"]
    if role["baseline"]["exists"]:
        backup = Path(role["baseline"]["backup"])
        temporary = target.with_name(target.name + ".record-rollback.tmp")
        shutil.copy2(backup, temporary)
        os.replace(temporary, target)
    else:
        target.unlink(missing_ok=True)

def _verify_roles(output: Path, roles: list[dict[str, Any]], state_name: str) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    for role in roles:
        expected = role[state_name]
        if role["kind"] == "file":
            actual = _file_state(output / role["path"])
            if actual["exists"] != expected["exists"] or actual["sha256"] != expected["sha256"]:
                errors.append({"role": role["name"], "expected": expected["sha256"], "actual": actual["sha256"]})
        elif role["name"] == "agent-index-note":
            actual_digest = _json_digest(_current_agent(output / role["path"], role["selector"]))
            if actual_digest != expected["sha256"]:
                errors.append({"role": role["name"], "expected": expected["sha256"], "actual": actual_digest})
        else:
            actual_digest = _json_digest(_current_machine(output / role["path"], role["selector"]))
            if actual_digest != expected["sha256"]:
                errors.append({"role": role["name"], "expected": expected["sha256"], "actual": actual_digest})
    return errors

def _relative_note_error(error: dict[str, Any], output: Path) -> dict[str, Any]:
    value = dict(error)
    if isinstance(value.get("path"), str):
        path = Path(value["path"].replace("\\", "/"))
        if not path.is_absolute():
            path = output / path
        try:
            value["path"] = path.resolve().relative_to(output.resolve()).as_posix()
        except ValueError:
            pass  # An unbound diagnostic can never match an eligible note.
    return value

def _note_error_baseline(output: Path, relative: Path) -> dict[str, Any]:
    errors = [_relative_note_error(error, output) for error in audit_notes(output)]
    unchanged_notes = {}
    for error in errors:
        path = Path(str(error.get("path", "")))
        if (error.get("reason") != "note-link-dangling" or len(path.parts) != 3
                or path.parts[0] != "markdown" or path.parts[1] not in NOTE_DIRECTORIES
                or path.suffix != ".md" or path == Path("markdown") / relative):
            continue
        human = output / "human" / Path(*path.parts[1:])
        markdown = output / path
        if human.is_file() and markdown.is_file() and human.read_bytes() == markdown.read_bytes():
            unchanged_notes[path.as_posix()] = sha256_file(markdown)
    return {"errors": errors, "unchanged_notes": unchanged_notes}

def _candidate_contract(candidate_output: Path, relative: Path, baseline: dict[str, Any]) -> dict[str, Any]:
    human = candidate_output / "human" / relative
    markdown = candidate_output / "markdown" / relative
    records_human = candidate_output / "human/RECORDS.md"
    records_markdown = candidate_output / "markdown/RECORDS.md"
    errors, unresolved = _replacement_note_errors(candidate_output, baseline)
    work_records = audit_work_record_index(candidate_output)
    if human.read_bytes() != markdown.read_bytes():
        errors.append({"reason": "candidate-note-mirror-differs", "path": relative.as_posix()})
    if records_human.read_bytes() != records_markdown.read_bytes():
        errors.append({"reason": "candidate-record-index-mirror-differs"})
    if work_records["status"] != "passed":
        errors.extend(work_records["errors"])
    if errors:
        raise CkbError(f"record replace candidate audit failed: {errors[:10]}")
    return {"status": "passed", "note_errors": [], "work_record_index": work_records,
            "verification_scope": "record-replacement", "maintenance_verified": False,
            "unresolved_baseline_diagnostics": unresolved}

def _restore_promoted(
    output: Path,
    roles: list[dict[str, Any]],
    promoted: list[str],
    agent_baseline: dict[str, Any],
    machine_baseline: dict[str, Any],
) -> None:
    by_name = {role["name"]: role for role in roles}
    for name in reversed(promoted):
        role = by_name[name]
        if role["kind"] == "file":
            _restore_file(output, role)
        elif name == "agent-index-note":
            current = _current_agent(output / role["path"], role["selector"])
            _commit_agent(output / role["path"], role["selector"], current, agent_baseline)
        else:
            current = _current_machine(output / role["path"], role["selector"])
            _commit_machine(output / role["path"], role["selector"], current, machine_baseline)

def _promotion(
    output: Path,
    manifest_path: Path,
    manifest: dict[str, Any],
    roles: list[dict[str, Any]],
    fault: str | None,
) -> dict[str, Any]:
    by_name = {role["name"]: role for role in roles}
    agent_role = by_name["agent-index-note"]
    machine_role = by_name["machine-knowledge-note"]
    agent_baseline = json_load(Path(agent_role["baseline"]["backup"]))
    agent_candidate = json_load(Path(agent_role["modified"]["candidate"]))
    machine_baseline = json_load(Path(machine_role["baseline"]["backup"]))
    machine_candidate = json_load(Path(machine_role["modified"]["candidate"]))
    sidecars = {
        role["name"]: {
            suffix: Path(str(output / role["path"]) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")
        }
        for role in (agent_role, machine_role)
    }
    promoted: list[str] = []
    manifest["status"] = "promoting"
    json_write(manifest_path, manifest)
    try:
        for role in roles:
            if role["kind"] == "file":
                _promote_file(output, role, role["baseline"]["sha256"])
            elif role["name"] == "agent-index-note":
                _commit_agent(output / role["path"], role["selector"], agent_baseline, agent_candidate)
            else:
                _commit_machine(output / role["path"], role["selector"], machine_baseline, machine_candidate)
            promoted.append(role["name"])
            if fault == f"after-{role['name']}":
                raise CkbError(f"injected record replace promotion failure after {role['name']}")
        verification_errors = _verify_roles(output, roles, "modified")
        note_errors, unresolved = _replacement_note_errors(output, manifest["note_error_baseline"])
        record_audit = audit_work_record_index(output)
        agent_audit = audit_agent_index(output)
        if verification_errors or note_errors or record_audit["status"] != "passed" or agent_audit["status"] != "passed":
            raise CkbError(
                "record replace post-promotion verification failed: "
                f"roles={verification_errors[:5]}; notes={note_errors[:5]}; records={record_audit['errors'][:5]}; "
                f"agent={agent_audit['errors'][:5]}"
            )
        manifest.update(
            {
                "status": "completed",
                "completed_at_utc": utc_now(),
                "verification": {
                    "status": "passed",
                    "role_errors": [],
                    "note_errors": [],
                    "verification_scope": "record-replacement",
                    "maintenance_verified": False,
                    "unresolved_baseline_diagnostics": unresolved,
                    "work_record_index": record_audit,
                    "agent_index": agent_audit,
                },
            }
        )
        json_write(manifest_path, manifest)
        journal = record_operation(output, "record", "record:replace", "replaced", [_journal_evidence(output, manifest_path)])
        manifest["operation_journal"] = journal
        json_write(manifest_path, manifest)
        return journal
    except Exception:
        _restore_promoted(output, roles, promoted, agent_baseline, machine_baseline)
        restored_errors = _verify_roles(output, roles, "baseline")
        manifest.update(
            {
                "status": "failed-restored" if not restored_errors else "failed-restore-incomplete",
                "failed_at_utc": utc_now(),
                "promoted_before_failure": promoted,
                "restore_errors": restored_errors,
            }
        )
        json_write(manifest_path, manifest)
        if restored_errors:
            raise CkbError(f"record replace failed and baseline restoration was incomplete: {restored_errors[:10]}")
        raise
    finally:
        _cleanup_new_sqlite_sidecars(output / agent_role["path"], sidecars[agent_role["name"]])
        _cleanup_new_sqlite_sidecars(output / machine_role["path"], sidecars[machine_role["name"]])

def _load_rollback_manifest(output: Path, manifest_path: Path) -> dict[str, Any]:
    manifest_path = manifest_path.resolve()
    root = _operation_root(output)
    try:
        manifest_path.relative_to(root)
    except ValueError as exc:
        raise CkbError(f"record rollback manifest must be inside this OUTPUT: {manifest_path}") from exc
    if not manifest_path.is_file():
        raise CkbError(f"record rollback manifest is missing: {manifest_path}")
    manifest = json_load(manifest_path)
    if manifest.get("schema_version") != RECORD_REPLACE_SCHEMA_VERSION or manifest.get("operation") != "record-replace":
        raise CkbError(f"unsupported record rollback manifest: {manifest_path}")
    if Path(str(manifest.get("output") or "")).resolve() != output.resolve():
        raise CkbError(f"record rollback manifest OUTPUT differs from the requested OUTPUT: {manifest_path}")
    if manifest.get("status") not in {"completed", "rolled-back"}:
        raise CkbError(f"record rollback requires a completed replacement: status={manifest.get('status')}")
    return manifest
